<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>Personal Expense Tracker</title>
<style>
  * { box-sizing: border-box; }
  body {
    font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
    margin: 0;
    padding: 20px;
    background: #f5f6f8;
    color: #1f2430;
    line-height: 1.5;
  }
  h1 { margin: 0 0 4px; font-size: 1.6rem; }
  .subtitle { color: #5b6472; margin: 0 0 24px; font-size: 0.95rem; }

  .layout {
    display: grid;
    grid-template-columns: minmax(280px, 360px) 1fr;
    gap: 24px;
    align-items: start;
  }
  @media (max-width: 760px) {
    .layout { grid-template-columns: 1fr; }
  }

  .card {
    background: #fff;
    border: 1px solid #e3e6ee;
    border-radius: 8px;
    padding: 18px;
    box-shadow: 0 1px 2px rgba(0,0,0,0.03);
  }
  .card + .card { margin-top: 16px; }

  label {
    display: block;
    font-size: 0.8rem;
    font-weight: 600;
    color: #3a4150;
    margin: 10px 0 4px;
  }
  input, select, textarea {
    width: 100%;
    padding: 8px 10px;
    font-size: 0.95rem;
    border: 1px solid #cdd3df;
    border-radius: 6px;
    background: #fff;
    color: #1f2430;
    font-family: inherit;
  }
  input:focus, select:focus, textarea:focus {
    outline: none;
    border-color: #4a6cf7;
    box-shadow: 0 0 0 3px rgba(74,108,247,0.15);
  }
  textarea { resize: vertical; min-height: 48px; }

  .btn {
    display: inline-block;
    border: none;
    border-radius: 6px;
    padding: 9px 16px;
    font-size: 0.95rem;
    font-weight: 600;
    cursor: pointer;
    background: #4a6cf7;
    color: #fff;
    transition: background 0.15s;
  }
  .btn:hover { background: #3a57d6; }
  .btn-secondary {
    background: #eef1f7;
    color: #3a4150;
  }
  .btn-secondary:hover { background: #e0e4ee; }

  .form-error {
    color: #c0292a;
    font-size: 0.85rem;
