    align-items: baseline;
    padding: 6px 0;
    border-bottom: 1px dashed #e3e6ee;
  }
  .summary-row:last-child { border-bottom: none; }
  .summary-row .label { font-size: 0.85rem; color: #5b6472; }
  .summary-row .value { font-weight: 600; }

  #total {
    font-size: 1.8rem;
