    color: #c0292a;
    border: none;
    border-radius: 6px;
    padding: 6px 10px;
    font-size: 0.8rem;
    cursor: pointer;
    font-weight: 600;
  }
  .exp-del:hover { background: #f9d7d7; }

  .empty {
    text-align: center;
    color: #8a93a3;
    padding: 24px 0;
    font-size: 0.9rem;
  }

  .toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 12px;
  }
  .toolbar h2 { margin: 0; font-size: 1.15rem; }
</style>
</head>
<body>
  <h1>Personal Expense Tracker</h1>
  <p class="subtitle">Track your spending, filter by category and date, and persist between sessions.</p>

  <div class="layout">
    <div>
      <div class="card">
        <h2 style="margin:0 0 8px; font-size:1.15rem;">Add Expense</h2>
        <form id="expense-form" autocomplete="off">
          <label for="amount">Amount</label>
          <input type="number" id="amount" step="0.01" min="0.01" placeholder="0.00" />

          <label for="category">Category</label>
          <select id="category">
            <option value="groceries">Groceries</option>
            <option value="transport">Transport</option>
            <option value="bills">Bills</option>
            <option value="fun">Fun</option>
          </select>

          <label for="date">Date</label>
          <input type="date" id="date" />

          <label for="note">Note (optional)</label>
          <textarea id="note" placeholder="e.g. weekly groceries"></textarea>

          <div id="form-error" class="form-error" role="alert" aria-live="polite"></div>

          <div style="margin-top:12px;">
            <button type="submit" id="add-expense" class="btn">Add Expense</button>
          </div>
        </form>
      </div>

      <div class="card">
        <div class="summary-row">
          <span class="label">Total (visible)</span>
          <span class="value" id="total">0.00</span>
        </div>
        <div class="cat-list" id="cat-summary">
          <!-- per-category totals injected here -->
        </div>
      </div>
    </div>

    <div>
      <div class="card">
        <div class="toolbar">
          <h2>Expenses</h2>
          <button id="clear-filters" class="btn btn-secondary" type="button">Clear Filters</button>
        </div>

        <div class="filters">
          <div class="full">
            <label for="filter-category">Category</label>
            <select id="filter-category">
              <option value="all">All</option>
              <option value="groceries">Groceries</option>
              <option value="transport">Transport</option>
              <option value="bills">Bills</option>
              <option value="fun">Fun</option>
            </select>
          </div>
          <div>
            <label for="filter-from">From</label>
            <input type="date" id="filter-from" />
          </div>
          <div>
            <label for="filter-to">To</label>
            <input type="date" id="filter-to" />
          </div>
        </div>
      </div>

      <div class="card">
        <ul id="expense-list" class="expense-list"></ul>
        <div id="empty-state" class="empty">No expenses to show.</div>
      </div>
    </div>
  </div>

<script>
(function () {
  "use strict";

  var CATEGORIES = ["groceries", "transport", "bills", "fun"];
  var STORAGE_KEY = "expense-tracker-data-v1";

  var expenses = []; // [{id, amount, category, date, note}]

  // ---------- DOM refs ----------
  var form        = document.getElementById("expense-form");
  var amountEl   = document.getElementById("amount");
  var categoryEl = document.getElementById("category");
  var dateEl     = document.getElementById("date");
  var noteEl     = document.getElementById("note");
  var formError  = document.getElementById("form-error");
  var addBtn     = document.getElementById("add-expense");

  var filterCatEl  = document.getElementById("filter-category");
  var filterFromEl = document.getElementById("filter-from");
  var filterToEl   = document.getElementById("filter-to");
  var clearBtn     = document.getElementById("clear-filters");

  var listEl     = document.getElementById("expense-list");
  var emptyEl    = document.getElementById("empty-state");
  var totalEl    = document.getElementById("total");
  var catSumEl   = document.getElementById("cat-summary");

  // ---------- Persistence ----------
  function loadExpenses() {
    try {
      var raw = localStorage.getItem(STORAGE_KEY);
      if (raw) {
        var parsed = JSON.parse(raw);
        if (Array.isArray(parsed)) {
          expenses = parsed.filter(function (e) {
            return e && typeof e.amount === "number" && e.category && e.date;
          });
        }
      }
    } catch (err) {
      expenses = [];
    }
  }

  function saveExpenses() {
    try {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
    } catch (err) {
      // ignore storage errors
    }
  }

  // ---------- Helpers ----------
  function formatAmount(n) {
    return n.toFixed(2);
  }

  function uid() {
    return Date.now().toString(36) + Math.random().toString(36).slice(2, 8);
  }

  function setFormError(msg) {
    formError.textContent = msg || "";
  }

  // ---------- Filtering ----------
  function isInRange(expenseDate, from, to) {
    if (from && expenseDate < from) return false;
    if (to && expenseDate > to) return false;
    return true;
  }

  function getVisibleExpenses() {
    var cat = filterCatEl.value;
    var from = filterFromEl.value;
    var to = filterToEl.value;
    return expenses.filter(function (e) {
      if (cat !== "all" && e.category !== cat) return false;
      if (!isInRange(e.date, from, to)) return false;
      return true;
    });
  }

  // ---------- Rendering ----------
  function renderList() {
    listEl.innerHTML = "";

    // newest first: sort by date desc, then id desc
    var sorted = expenses.slice().sort(function (a, b) {
      if (a.date !== b.date) return a.date < b.date ? 1 : -1;
      return a.id < b.id ? 1 : -1;
    });

    var visible = getVisibleExpenses();
    var visibleIds = {};
    visible.forEach(function (e) { visibleIds[e.id] = true; });

    sorted.forEach(function (exp) {
      var li = document.createElement("li");
      li.className = "expense";
      if (!visibleIds[exp.id]) {
        li.style.display = "none";
      }

      var main = document.createElement("div");
      main.className = "main";

      var amountLine = document.createElement("div");
      amountLine.className = "amount";
      amountLine.textContent = "$" + formatAmount(exp.amount);

      var badge = document.createElement("span");
      badge.className = "badge";
      badge.textContent = exp.category;
      amountLine.appendChild(badge);

      var dateSpan = document.createElement("span");
      dateSpan.textContent = exp.date;
      dateSpan.style.fontSize = "0.82rem";
      dateSpan.style.color = "#5b6472";
      amountLine.appendChild(dateSpan);

      main.appendChild(amountLine);

      if (exp.note) {
        var noteDiv = document.createElement("div");
        noteDiv.className = "note-text";
        noteDiv.textContent = exp.note;
        main.appendChild(noteDiv);
      }

      li.appendChild(main);

      var delBtn = document.createElement("button");
      delBtn.type = "button";
      delBtn.className = "exp-del";
      delBtn.textContent = "Delete";
      delBtn.setAttribute("data-id", exp.id);
      delBtn.addEventListener("click", function () {
        deleteExpense(exp.id);
      });

      li.appendChild(delBtn);
      listEl.appendChild(li);
    });

    emptyEl.style.display = (visible.length === 0) ? "block" : "none";
  }

  function renderSummary() {
    var visible = getVisibleExpenses();
    var total = 0;
    var byCat = {};
    CATEGORIES.forEach(function (c) { byCat[c] = 0; });

    visible.forEach(function (e) {
      total += e.amount;
      if (byCat[e.category] !== undefined) {
        byCat[e.category] += e.amount;
      }
    });

    totalEl.textContent = formatAmount(total);

    catSumEl.innerHTML = "";
    CATEGORIES.forEach(function (c) {
      var div = document.createElement("div");
      div.className = "cat-total";
      div.setAttribute("data-cat", c);

      var name = document.createElement("span");
      name.className = "cat-name";
      name.textContent = c;

      var amt = document.createElement("span");
      amt.className = "cat-amount";
      amt.textContent = formatAmount(byCat[c]);

      div.appendChild(name);
      div.appendChild(amt);
      catSumEl.appendChild(div);
    });
  }

  function render() {
    renderList();
    renderSummary();
  }

  // ---------- Actions ----------
  function addExpense(data) {
    var exp = {
      id: uid(),
      amount: data.amount,
      category: data.category,
      date: data.date,
      note: data.note || ""
    };
    expenses.push(exp);
    saveExpenses();
    render();
  }

  function deleteExpense(id) {
    expenses = expenses.filter(function (e) { return e.id !== id; });
    saveExpenses();
    render();
  }

  // ---------- Form submission ----------
  form.addEventListener("submit", function (evt) {
    evt.preventDefault();

    var rawAmount = amountEl.value;
    var amountNum = parseFloat(rawAmount);
    var dateVal = dateEl.value;

    // Validation
    if (rawAmount === "" || isNaN(amountNum) || !isFinite(amountNum) || amountNum <= 0) {
      setFormError("Please enter a valid positive amount.");
      return;
    }
    if (!dateVal) {
      setFormError("Please select a date.");
      return;
    }

    // Validate category is one of allowed
    var cat = categoryEl.value;
    if (CATEGORIES.indexOf(cat) === -1) {
      setFormError("Invalid category selected.");
      return;
    }

    setFormError("");
    addExpense({
      amount: Math.round(amountNum * 100) / 100,
      category: cat,
      date: dateVal,
      note: noteEl.value.trim()
    });

    // Reset amount field (per contract)
    amountEl.value = "";
    amountEl.focus();
  });

  // ---------- Filter listeners ----------
  filterCatEl.addEventListener("change", render);
  filterFromEl.addEventListener("change", render);
  filterToEl.addEventListener("change", render);

  clearBtn.addEventListener("click", function () {
    filterCatEl.value = "all";
    filterFromEl.value = "";
    filterToEl.value = "";
    render();
  });

  // ---------- Init ----------
  function setDefaultDate() {
    if (!dateEl.value) {
      var today = new Date();
      var yyyy = today.getFullYear();
      var mm = String(today.getMonth() + 1).padStart(2, "0");
      var dd = String(today.getDate()).padStart(2, "0");
      dateEl.value = yyyy + "-" + mm + "-" + dd;
    }
  }

  loadExpenses();
  setDefaultDate();
  render();
})();
</script>
</body>
</html>
